2235   private async runTurnLoopWithHeadlessDrain(args: {
2236     turnLoop: TurnLoop;
2237     messages: Message[];
2238     applyGoalTermination: ReturnType<typeof createGoalTerminationApplier>;
2239     session: SessionBundle;
2240     options: EngineRunOptions | undefined;
2241   }): Promise<{
2242     result: Awaited<ReturnType<TurnLoop["run"]>>;
2243     firstGoalTermination: GoalTerminationReason | undefined;
2244   }> {
2245     const { turnLoop, messages, applyGoalTermination, session, options } = args;
2246 
2247     let result = await turnLoop.run(messages);
2248     let firstGoalTermination: GoalTerminationReason | undefined = result.goalTermination;
2249     applyGoalTermination(result.goalTermination, result.goalTerminationRound);
2250 
2251     // ── Headless: drain background sub-agents before resolving ───────
2252     // Unified background-work model (2026-06-17): the engine NO LONGER parks
2253     // every run waiting on background work. Background work (sub-agents,
2254     // video polls, shells) ends the turn, yields, and is picked up later by
2255     // the server's notification-wakeup path (maybeWakeIdleSession). The
2256     // INTERACTIVE path relies on that wakeup + a run-boundary re-check.
2257     //
2258     // HEADLESS is the exception: a one-shot `engine.run` whose caller takes
2259     // `result.text` as THE answer (automation / SDK) has no later turn to
2260     // pick up a wakeup — so it must wait, before resolving, until its own
2261     // background SUB-AGENTS finish and summarize. Only sub-agents (their
2262     // summary IS part of this run's result), NOT shells (a dev server never
2263     // exits → would hang headless forever) and NOT video (a long render the
2264     // one-shot run shouldn't block on). This replaces the old for(;;) park
2265     // (s-mpvf4rsj-bb6e4639 invariant) for the headless case only.
2266     const sid = session.state.sessionId;
2267     const isTopLevel = this.config.isSubAgent !== true;
2268     if (isTopLevel && this.isHeadless()) {
2269       result = await drainHeadlessBackgroundAgents({
2270         sid,
2271         session,
2272         signal: options?.signal,
2273         initialResult: result,
2274         runTurnLoop: (msgs) => turnLoop.run(msgs),
2275         applyGoalTermination,
2276         waitForBackgroundAgentChange: (s, sig) => this.waitForBackgroundAgentChange(s, sig),
2277         waitForBackgroundAgentChangeOrTimeout: (s, ms) =>
2278           this.waitForBackgroundAgentChangeOrTimeout(s, ms),
2279         getFirstGoalTermination: () => firstGoalTermination,
2280         setFirstGoalTermination: (t) => {
2281           firstGoalTermination = t;
2282         },
2283       });
2284     }
2285 
2286     return { result, firstGoalTermination };
2287   }
